item.appendChild(chInfo(c.name, [c.subs, c.videos].filter(Boolean).join(' \xB7 ')));
var added = channels.some(function (x) { return x.id === c.id; });
var b = chBtn(added ? '\u5DF2\u52A0\u5165' : '\u52A0\u5165', 'add', c.id);
b.dataset.name = c.name || '';
